int process_gif_image(struct iwgifrcontext* rctx) {
    if (!rctx) {
        return 0;
    }

    // Read image header
    if (fread(&rctx->image_descriptor, sizeof(rctx->image_descriptor), 1, rctx->file) != 1) {
        return 0;
    }

    // Extract dimensions and interlacing information
    rctx->image_width = rctx->image_descriptor.width;
    rctx->image_height = rctx->image_descriptor.height;
    rctx->interlaced = (rctx->image_descriptor.flags & 0x40) != 0;

    // Initialize color tables if a local color table is present
    if (rctx->image_descriptor.flags & 0x80) {
        int color_table_size = 2 << (rctx->image_descriptor.flags & 0x07);
        if (color_table_size > GIF_MAX_COLOR_TABLE_SIZE) {
            return 0;
        }

        if (fread(rctx->local_color_table, sizeof(uint32_t), color_table_size, rctx->file) != color_table_size) {
            return 0;
        }

        // Handle transparency by modifying the color table
        if (rctx->image_descriptor.flags & 0x01) {
            int transparent_index = rctx->transparent_index;
            if (transparent_index >= 0 && transparent_index < color_table_size) {
                rctx->local_color_table[transparent_index] |= GIF_TRANSPARENT_FLAG;
            }
        }
    }

    // Read LZW code size
    uint8_t lzw_code_size;
    if (fread(&lzw_code_size, sizeof(lzw_code_size), 1, rctx->file) != 1) {
        return 0;
    }

    // Validate LZW code size against GIF specification
    if (lzw_code_size < 2 || lzw_code_size > 8) {
        return 0;
    }

    // Initialize screen context
    if (!initialize_screen_context(rctx, rctx->image_width, rctx->image_height)) {
        return 0;
    }

    // Read pixel data in subblocks
    uint8_t subblock_size;
    while (fread(&subblock_size, sizeof(subblock_size), 1, rctx->file) == 1 && subblock_size != 0) {
        if (subblock_size > GIF_MAX_SUBBLOCK_SIZE) {
            return 0;
        }

        uint8_t subblock_data[GIF_MAX_SUBBLOCK_SIZE];
        if (fread(subblock_data, sizeof(uint8_t), subblock_size, rctx->file) != subblock_size) {
            return 0;
        }

        // Process subblock with LZW decoding
        if (!decode_lzw_subblock(rctx, subblock_data, subblock_size, lzw_code_size)) {
            return 0;
        }
    }

    // Check for end of image
    if (feof(rctx->file)) {
        return 0;
    }

    return 1;
}
